// P1 - 封面：森马品牌成交人群画像对比分析
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442',
    accent1: 'B44626',
    accent2: '5A6675',
    light:   'F7F6F3',
    ink:     '242830',
    muted:   '626773',
    line:    'DEDCD6'
  };

  const s = pptx.addSlide();

  // 主色满版底
  s.background = { color: t.primary };

  // 右上角装饰几何（accent2 方块）
  s.addShape('rect', {
    x: 11.6, y: 0.4, w: 1.4, h: 0.08,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });
  s.addShape('rect', {
    x: 11.6, y: 0.58, w: 0.7, h: 0.08,
    fill: { color: 'FFFFFF' }, line: { color: 'FFFFFF' }
  });

  // 左侧细长色条
  s.addShape('rect', {
    x: 0.7, y: 3.0, w: 0.12, h: 1.5,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });

  // 顶部小标（英文）
  s.addText('SEMIR  ·  AUDIENCE PROFILE COMPARISON', {
    x: 0.95, y: 2.6, w: 11.0, h: 0.4,
    fontSize: 12, fontFace: 'Arial',
    color: t.accent2, charSpacing: 6
  });

  // 主标题（中文，两行）
  s.addText('森马品牌成交人群画像', {
    x: 0.95, y: 3.05, w: 11.0, h: 0.85,
    fontSize: 40, fontFace: 'Microsoft YaHei',
    color: 'FFFFFF', bold: true
  });
  s.addText('对比分析报告', {
    x: 0.95, y: 3.85, w: 11.0, h: 0.85,
    fontSize: 40, fontFace: 'Microsoft YaHei',
    color: 'FFFFFF', bold: true
  });

  // 副标题（对比周期）
  s.addText('2025 年 9 月  vs  2026 年 9 月', {
    x: 0.95, y: 4.85, w: 11.0, h: 0.5,
    fontSize: 18, fontFace: 'Microsoft YaHei',
    color: 'DEDCD6'
  });

  // 汇报信息
  s.addText('品牌运营复盘  ·  成交人群对比洞察', {
    x: 0.95, y: 6.0, w: 11.0, h: 0.4,
    fontSize: 12, fontFace: 'Microsoft YaHei',
    color: '8C97A6'
  });

  // 底部 accent2 横条
  s.addShape('rect', {
    x: 0, y: 7.38, w: 13.33, h: 0.12,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });

  // 右下角数据源标识
  s.addText('DATA SOURCE  ·  阿里达摩盘 ·  品牌成交画像', {
    x: 7.0, y: 6.95, w: 6.0, h: 0.3,
    fontSize: 9, fontFace: 'Arial',
    color: '8C97A6', align: 'right', charSpacing: 3
  });

  return s;
}

// P2 - 摘要页：对比框架与核心洞察
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442',
    accent1: 'B44626',
    accent2: '5A6675',
    light:   'F7F6F3',
    ink:     '242830',
    muted:   '626773',
    line:    'DEDCD6'
  };

  const s = pptx.addSlide();
  s.background = { color: 'FFFFFF' };

  // 顶部标题区
  s.addShape('rect', {
    x: 0, y: 0, w: 13.33, h: 0.06,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });
  s.addText('EXECUTIVE  SUMMARY', {
    x: 0.6, y: 0.4, w: 6.0, h: 0.3,
    fontSize: 10, fontFace: 'Arial',
    color: t.accent1, charSpacing: 6, bold: true
  });
  s.addText('对比框架与核心洞察', {
    x: 0.6, y: 0.75, w: 8.0, h: 0.6,
    fontSize: 26, fontFace: 'Microsoft YaHei',
    color: t.primary, bold: true
  });
  s.addText('基于 2025.09 与 2026.09 两期成交人群画像数据，提炼 5 条关键变化结论', {
    x: 0.6, y: 1.35, w: 11.5, h: 0.35,
    fontSize: 12, fontFace: 'Microsoft YaHei',
    color: t.muted
  });

  // 顶部 4 张 KPI 概览卡
  const kpis = [
    { label: '女性占比',         now: '85.87%', delta: '+2.68pp' },
    { label: '24-30 岁主力占比',  now: '31.77%', delta: '+0.66pp' },
    { label: 'GenZ 群体占比',     now: '15.82%', delta: '+3.84pp' },
    { label: '抖音时尚兴趣',     now: '76.07%', delta: '+2.81pp' }
  ];
  const cardW = 2.95, cardH = 1.4, cardY = 1.95, gap = 0.18;
  const startX = 0.6;
  kpis.forEach((k, i) => {
    const x = startX + i * (cardW + gap);
    s.addShape('rect', {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: t.light }, line: { color: t.line, width: 0.5 }
    });
    s.addShape('rect', {
      x, y: cardY, w: 0.08, h: cardH,
      fill: { color: t.accent1 }, line: { color: t.accent1 }
    });
    s.addText(k.label, {
      x: x + 0.22, y: cardY + 0.15, w: cardW - 0.3, h: 0.3,
      fontSize: 11, fontFace: 'Microsoft YaHei', color: t.muted
    });
    s.addText(k.now, {
      x: x + 0.22, y: cardY + 0.45, w: cardW - 0.3, h: 0.55,
      fontSize: 28, fontFace: 'Arial', color: t.primary, bold: true
    });
    s.addText(k.delta, {
      x: x + 0.22, y: cardY + 1.0, w: cardW - 0.3, h: 0.3,
      fontSize: 12, fontFace: 'Arial', color: t.accent1, bold: true
    });
  });

  // 5 条洞察列表
  const insights = [
    { idx: '01', title: '女性占比进一步上升至 85.87%', desc: '同比 +2.68pp，男士成交占比由 16.81% 收窄至 14.13%' },
    { idx: '02', title: '主力人群仍为 24-30 岁（31.77%）', desc: '20-23 岁年轻段占比提升 2.87pp，年轻化趋势延续' },
    { idx: '03', title: '山东、河南占比反超浙江、广东',     desc: '山东 +0.78pp、河南 +0.85pp，珠三角优势收窄' },
    { idx: '04', title: 'GenZ 群体占比跃升 3.84pp',     desc: '精致妈妈微降 0.46pp，结构由「妈妈主导」转向「年轻 + 妈妈」双核' },
    { idx: '05', title: '抖音时尚 / 美妆品类同步上扬',     desc: '时尚视频兴趣 +2.81pp、彩妆香水成交 +3.76pp' }
  ];
  const itemY0 = 3.65;
  const itemH = 0.62;
  insights.forEach((it, i) => {
    const y = itemY0 + i * itemH;
    s.addText(it.idx, {
      x: 0.6, y, w: 0.55, h: itemH,
      fontSize: 18, fontFace: 'Arial', color: t.accent1, bold: true
    });
    s.addShape('rect', {
      x: 1.2, y: y + 0.1, w: 0.04, h: itemH - 0.2,
      fill: { color: t.line }, line: { color: t.line }
    });
    s.addText(it.title, {
      x: 1.4, y: y + 0.04, w: 6.4, h: 0.32,
      fontSize: 13, fontFace: 'Microsoft YaHei', color: t.ink, bold: true
    });
    s.addText(it.desc, {
      x: 1.4, y: y + 0.32, w: 11.0, h: 0.28,
      fontSize: 11, fontFace: 'Microsoft YaHei', color: t.muted
    });
  });

  // 右下角数据范围卡片
  s.addShape('rect', {
    x: 8.3, y: 4.55, w: 4.4, h: 2.0,
    fill: { color: t.primary }, line: { color: t.primary }
  });
  s.addText('对比口径', {
    x: 8.5, y: 4.7, w: 4.0, h: 0.3,
    fontSize: 10, fontFace: 'Arial', color: t.accent2, charSpacing: 4, bold: true
  });
  s.addText('森马品牌成交人群画像', {
    x: 8.5, y: 4.95, w: 4.0, h: 0.35,
    fontSize: 14, fontFace: 'Microsoft YaHei', color: 'FFFFFF', bold: true
  });
  s.addText([
    { text: '周期A  ', options: { color: 'DEDCD6', fontSize: 10 } },
    { text: '2025 年 9 月\n', options: { color: 'FFFFFF', fontSize: 12, bold: true, breakLine: true } },
    { text: '周期B  ', options: { color: 'DEDCD6', fontSize: 10 } },
    { text: '2026 年 9 月\n', options: { color: 'FFFFFF', fontSize: 12, bold: true, breakLine: true } },
    { text: '维度  ', options: { color: 'DEDCD6', fontSize: 10 } },
    { text: '性别、年龄、地域、消费群体', options: { color: 'FFFFFF', fontSize: 11 } }
  ], {
    x: 8.5, y: 5.4, w: 4.0, h: 1.4,
    fontFace: 'Microsoft YaHei', valign: 'top', paraSpaceAfter: 6
  });

  // 页码徽章
  s.addShape('ellipse', {
    x: 12.55, y: 6.95, w: 0.38, h: 0.38,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });
  s.addText('02', {
    x: 12.55, y: 6.95, w: 0.38, h: 0.38,
    fontSize: 10, color: 'FFFFFF', align: 'center', bold: true
  });

  return s;
}

// P3 - 性别年龄对比
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442',
    accent1: 'B44626',
    accent2: '5A6675',
    light:   'F7F6F3',
    ink:     '242830',
    muted:   '626773',
    line:    'DEDCD6'
  };

  const s = pptx.addSlide();
  s.background = { color: 'FFFFFF' };

  // 顶部标题区
  s.addShape('rect', {
    x: 0, y: 0, w: 13.33, h: 0.06,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });
  s.addText('SECTION  ·  GENDER  &  AGE', {
    x: 0.6, y: 0.4, w: 6.0, h: 0.3,
    fontSize: 10, fontFace: 'Arial',
    color: t.accent1, charSpacing: 6, bold: true
  });
  s.addText('女性占比进一步上升至 85.87%，主力人群仍为 24-30 岁', {
    x: 0.6, y: 0.75, w: 12.5, h: 0.55,
    fontSize: 22, fontFace: 'Microsoft YaHei',
    color: t.primary, bold: true
  });

  // ===== 性别对比 双栏 =====
  // 区块标题
  s.addText('性别结构', {
    x: 0.6, y: 1.55, w: 4.0, h: 0.35,
    fontSize: 14, fontFace: 'Microsoft YaHei',
    color: t.ink, bold: true
  });

  // 左栏 2025.09
  drawGenderColumn(s, t, 0.6, 2.0, '2025.09', '16.81%', '83.19%', t.muted);
  // 右栏 2026.09
  drawGenderColumn(s, t, 3.85, 2.0, '2026.09', '14.13%', '85.87%', t.accent1);

  // 性别变化箭头 / delta
  s.addShape('rect', {
    x: 6.95, y: 2.4, w: 0.04, h: 1.6,
    fill: { color: t.line }, line: { color: t.line }
  });
  s.addText('YoY Δ', {
    x: 7.05, y: 2.4, w: 1.2, h: 0.3,
    fontSize: 10, fontFace: 'Arial', color: t.muted, charSpacing: 4, bold: true
  });
  s.addText('女 +2.68pp', {
    x: 7.05, y: 2.75, w: 1.8, h: 0.35,
    fontSize: 16, fontFace: 'Arial', color: t.accent1, bold: true
  });
  s.addText('男 -2.68pp', {
    x: 7.05, y: 3.15, w: 1.8, h: 0.35,
    fontSize: 16, fontFace: 'Arial', color: t.primary, bold: true
  });
  s.addText('女性主导进一步强化', {
    x: 7.05, y: 3.55, w: 2.0, h: 0.4,
    fontSize: 11, fontFace: 'Microsoft YaHei', color: t.muted
  });

  // ===== 年龄段对比 =====
  s.addShape('rect', {
    x: 0.6, y: 4.55, w: 12.1, h: 0.04,
    fill: { color: t.line }, line: { color: t.line }
  });
  s.addText('年龄段占比分布', {
    x: 0.6, y: 4.7, w: 6.0, h: 0.35,
    fontSize: 14, fontFace: 'Microsoft YaHei',
    color: t.ink, bold: true
  });

  // 年龄段表格（8 行）
  const ageRows = [
    { age: '18-19', a25: '1.13%',  a26: '2.57%',  delta: '+1.44' },
    { age: '20-23', a25: '10.34%', a26: '13.21%', delta: '+2.87' },
    { age: '24-30', a25: '31.11%', a26: '31.77%', delta: '+0.66', highlight: true },
    { age: '31-35', a25: '17.42%', a26: '16.98%', delta: '-0.44' },
    { age: '36-40', a25: '25.13%', a26: '22.65%', delta: '-2.48', highlight: true },
    { age: '41-45', a25: '7.53%',  a26: '6.66%',  delta: '-0.87' },
    { age: '46-50', a25: '4.45%',  a26: '3.87%',  delta: '-0.58' },
    { age: '51+',   a25: '2.90%',  a26: '2.29%',  delta: '-0.61' }
  ];
  const tableX = 0.6, tableY = 5.15;
  const colAgeX = tableX;
  const colA25X = tableX + 1.4;
  const colA26X = tableX + 3.4;
  const colDeltaX = tableX + 5.6;
  const barX = tableX + 7.2;
  const rowH = 0.27;

  // 表头
  s.addText('年龄段', {
    x: colAgeX, y: tableY, w: 1.3, h: 0.3,
    fontSize: 10, fontFace: 'Microsoft YaHei', color: t.muted, bold: true, charSpacing: 2
  });
  s.addText('2025.09', {
    x: colA25X, y: tableY, w: 1.8, h: 0.3,
    fontSize: 10, fontFace: 'Arial', color: t.muted, bold: true, align: 'center'
  });
  s.addText('2026.09', {
    x: colA26X, y: tableY, w: 1.8, h: 0.3,
    fontSize: 10, fontFace: 'Arial', color: t.muted, bold: true, align: 'center'
  });
  s.addText('YoY Δ', {
    x: colDeltaX, y: tableY, w: 1.2, h: 0.3,
    fontSize: 10, fontFace: 'Arial', color: t.muted, bold: true, align: 'center'
  });
  s.addText('26.09 占比可视化', {
    x: barX, y: tableY, w: 5.5, h: 0.3,
    fontSize: 10, fontFace: 'Microsoft YaHei', color: t.muted, bold: true
  });

  ageRows.forEach((r, i) => {
    const y = tableY + 0.35 + i * rowH;
    if (i % 2 === 0) {
      s.addShape('rect', {
        x: tableX - 0.1, y: y - 0.02, w: 12.5, h: rowH,
        fill: { color: t.light }, line: { color: t.light }
      });
    }
    s.addText(r.age, {
      x: colAgeX, y, w: 1.3, h: rowH,
      fontSize: 12, fontFace: 'Arial', color: t.ink, bold: r.highlight
    });
    s.addText(r.a25, {
      x: colA25X, y, w: 1.8, h: rowH,
      fontSize: 12, fontFace: 'Arial', color: t.muted, align: 'center'
    });
    s.addText(r.a26, {
      x: colA26X, y, w: 1.8, h: rowH,
      fontSize: 12, fontFace: 'Arial', color: r.highlight ? t.accent1 : t.primary, bold: true, align: 'center'
    });
    const deltaColor = r.delta.startsWith('+') ? t.accent1 : t.primary;
    s.addText(r.delta + 'pp', {
      x: colDeltaX, y, w: 1.4, h: rowH,
      fontSize: 11, fontFace: 'Arial', color: deltaColor, bold: true, align: 'center'
    });

    // 26.09 可视化条
    const num = parseFloat(r.a26);
    const maxNum = 31.77;
    const barLen = (num / maxNum) * 4.8;
    const barColor = r.highlight ? t.accent1 : t.primary;
    s.addShape('rect', {
      x: barX, y: y + 0.07, w: barLen, h: 0.13,
      fill: { color: barColor }, line: { color: barColor }
    });
  });

  // 结论条
  s.addShape('rect', {
    x: 0.6, y: 7.0, w: 12.1, h: 0.32,
    fill: { color: t.primary }, line: { color: t.primary }
  });
  s.addText('洞察：成交人群进一步「年轻化 + 女性化」，20-23 岁年轻段是核心增量来源', {
    x: 0.7, y: 7.0, w: 12.0, h: 0.32,
    fontSize: 12, fontFace: 'Microsoft YaHei', color: 'FFFFFF', valign: 'middle'
  });

  // 页码徽章
  s.addShape('ellipse', {
    x: 12.55, y: 6.5, w: 0.38, h: 0.38,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });
  s.addText('03', {
    x: 12.55, y: 6.5, w: 0.38, h: 0.38,
    fontSize: 10, color: 'FFFFFF', align: 'center', bold: true
  });

  return s;
}

function drawGenderColumn(s, t, x, y, label, malePct, femalePct, accentColor) {
  const colW = 3.1, colTop = y;
  // 周期标签
  s.addShape('rect', {
    x, y: colTop, w: colW, h: 0.4,
    fill: { color: t.primary }, line: { color: t.primary }
  });
  s.addText(label, {
    x, y: colTop, w: colW, h: 0.4,
    fontSize: 13, fontFace: 'Arial', color: 'FFFFFF', bold: true, align: 'center', valign: 'middle', charSpacing: 4
  });
  // 女性条（主，占据大头）
  const femNum = parseFloat(femalePct);
  const maleNum = parseFloat(malePct);
  s.addText('女性', {
    x: x + 0.2, y: colTop + 0.55, w: 1.0, h: 0.3,
    fontSize: 11, fontFace: 'Microsoft YaHei', color: t.muted
  });
  s.addText(femalePct, {
    x: x + 0.2, y: colTop + 0.85, w: colW - 0.4, h: 0.7,
    fontSize: 36, fontFace: 'Arial', color: accentColor, bold: true
  });
  // 女性进度条
  s.addShape('rect', {
    x: x + 0.2, y: colTop + 1.65, w: colW - 0.4, h: 0.18,
    fill: { color: t.line }, line: { color: t.line }
  });
  s.addShape('rect', {
    x: x + 0.2, y: colTop + 1.65, w: (colW - 0.4) * femNum / 100, h: 0.18,
    fill: { color: accentColor }, line: { color: accentColor }
  });

  // 男性条
  s.addText('男性', {
    x: x + 0.2, y: colTop + 1.95, w: 1.0, h: 0.3,
    fontSize: 11, fontFace: 'Microsoft YaHei', color: t.muted
  });
  s.addText(malePct, {
    x: x + 0.2, y: colTop + 2.2, w: colW - 0.4, h: 0.45,
    fontSize: 20, fontFace: 'Arial', color: t.primary, bold: true
  });
  s.addShape('rect', {
    x: x + 0.2, y: colTop + 2.65, w: colW - 0.4, h: 0.14,
    fill: { color: t.line }, line: { color: t.line }
  });
  s.addShape('rect', {
    x: x + 0.2, y: colTop + 2.65, w: (colW - 0.4) * maleNum / 100, h: 0.14,
    fill: { color: t.muted }, line: { color: t.muted }
  });
}

// P4 - 地域结构对比：Top 10 省份
import pptxgen from 'pptxgenjs';

export function buildSlide(pptx) {
  const t = {
    primary: '263442',
    accent1: 'B44626',
    accent2: '5A6675',
    light:   'F7F6F3',
    ink:     '242830',
    muted:   '626773',
    line:    'DEDCD6'
  };

  const s = pptx.addSlide();
  s.background = { color: 'FFFFFF' };

  // 顶部标题区
  s.addShape('rect', {
    x: 0, y: 0, w: 13.33, h: 0.06,
    fill: { color: t.accent1 }, line: { color: t.accent1 }
  });
  s.addText('SECTION  ·  GEOGRAPHY', {
    x: 0.6, y: 0.4, w: 6.0, h: 0.3,
    fontSize: 10, fontFace: 'Arial',
    color: t.accent1, charSpacing: 6, bold: true
  });
  s.addText('地域结构微调：山东、河南反超，浙江、广东下沉', {
    x: 0.6, y: 0.75, w: 12.5, h: 0.55,
    fontSize: 22, fontFace: 'Microsoft YaHei',
    color: t.primary, bold: true
  });
  s.addText('两期 Top 10 省份占比与排名变化 · 数据口径：成交用户地域分布', {
    x: 0.6, y: 1.32, w: 12.0, h: 0.3,
    fontSize: 11, fontFace: 'Microsoft YaHei', color: t.muted
  });

  // ===== 双栏表格 =====
  const tableX = 0.6, tableY = 1.85;
  const colRank = tableX;
  const colProv = tableX + 0.6;
  const colA25 = tableX + 2.6;
  const colA26 = tableX + 4.4;
  const colDelta = tableX + 6.3;
  const colTgi = tableX + 7.7;
  const colBar = tableX + 9.4;

  // 表头
  s.addShape('rect', {
    x: colRank, y: tableY, w: 12.1, h: 0.4,
